package zone.moddev.mc.ironagearchitecture;

import java.util.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.math.*;
import org.junit.Test;
import static org.junit.Assert.*;
import zone.moddev.mc.ironagearchitecture.roof.*;

public class RoofDesignTest {
    private RoofPlan plan(int pitch,boolean along){RoofPlan p=new RoofPlan();p.minX=0;p.maxX=13;p.minZ=0;p.maxZ=12;p.floorY=64;p.pitch=pitch;p.alongX=along;return RoofPlanner.solve(p);}
    private RoofFeature feature(RoofPlan p,int type){RoofFeature f=new RoofFeature();f.id=1;f.type=type;f.u=1;f.v=4;f.width=type==RoofFeature.WINDOW?1:3;return f;}
    @Test public void legacyDrawingsKeepTheOriginalSolver(){RoofPlan p=plan(1,false);p.version=1;RoofPlanner.solve(p);NBTTagCompound n=p.write(new NBTTagCompound());n.removeTag("version");n.removeTag("design");n.removeTag("overhang");n.removeTag("features");RoofPlan restored=RoofPlan.read(n);assertEquals(1,restored.version);assertEquals(p.cells,RoofPlanner.solve(restored).cells);}
    @Test public void allPitchesAxesAndWoodsRoundTrip(){for(int pitch=0;pitch<3;pitch++)for(boolean axis:new boolean[]{false,true})for(int wood=0;wood<6;wood++){RoofPlan p=plan(pitch,axis);p.wood=wood;RoofPlanner.solve(p);assertTrue(p.error,p.valid());RoofPlan restored=RoofPlan.read(p.write(new NBTTagCompound()));assertEquals(p.cells,restored.cells);assertEquals(p.cells,RoofPlanner.solve(restored).cells);}}
    @Test public void independentOverhangsMoveOnlyTheirChosenBoundary(){RoofPlan p=plan(1,false);p.overhang[0]=0;p.overhang[1]=4;p.overhang[2]=0;p.overhang[3]=3;RoofPlanner.solve(p);assertTrue(p.error,p.valid());int minX=100,maxX=-100,minZ=100,maxZ=-100;for(long k:p.cells.keySet()){BlockPos a=BlockPos.fromLong(k);minX=Math.min(minX,a.getX());maxX=Math.max(maxX,a.getX());minZ=Math.min(minZ,a.getZ());maxZ=Math.max(maxZ,a.getZ());}assertEquals(0,minX);assertEquals(15,maxX);assertEquals(0,minZ);assertEquals(14,maxZ);}
    @Test public void eaveDropDoesNotRaiseTheInteriorRoof(){RoofPlan p=plan(1,false);p.drop=0;double ridge=RoofDesignPlanner.surface(p,7),edge=RoofDesignPlanner.surface(p,-1);p.drop=4;assertEquals(ridge,RoofDesignPlanner.surface(p,7),0);assertEquals(edge-1,RoofDesignPlanner.surface(p,-1),1e-9);}
    @Test public void mansardSidesMeetAtTheSameRidge(){for(int mask=1;mask<4;mask++){RoofPlan p=plan(1,false);p.mansard=mask;RoofPlanner.solve(p);assertTrue(p.error,p.valid());double ridge=RoofDesignPlanner.surface(p,7);assertEquals(72.25,ridge,1e-6);assertEquals(ridge,RoofDesignPlanner.surface(p,7-1e-8),1e-6);assertEquals(ridge,RoofDesignPlanner.surface(p,7+1e-8),1e-6);}}
    @Test public void atticAndOpenVaultPresetsChangeOnlyTheStructuralKit(){RoofPlan p=plan(1,false);int traditional=p.timber();p.frame=1;p.clearance=5;RoofPlanner.solve(p);assertTrue(p.error,p.valid());p.frame=2;RoofPlanner.solve(p);assertTrue(p.error,p.valid());assertTrue(p.timber()<=traditional);}
    @Test public void insufficientAtticClearanceIsAnExplicitFailure(){RoofPlan p=plan(0,false);p.frame=1;p.clearance=12;RoofPlanner.solve(p);assertFalse(p.valid());assertTrue(p.error.contains("clearance"));}
    @Test public void windowsAndBothDormersProducePaidOwnedFragments(){for(int type=0;type<3;type++){RoofPlan p=plan(1,false);p.features.add(feature(p,type));RoofPlanner.solve(p);assertTrue(p.error,p.valid());Set<String> windows=new HashSet<>();for(RoofCell c:p.cells.values())for(RoofWindow w:c.windows){windows.add(w.id);assertNotNull(p.cells.get(w.owner.toLong()));assertTrue(p.cells.get(w.owner.toLong()).parts.stream().anyMatch(a->a.id.equals(w.id)));}assertFalse(windows.isEmpty());for(RoofCell c:p.cells.values())for(RoofPart part:c.parts)assertTrue(p.cells.get(part.root.toLong()).parts.stream().anyMatch(a->a.id.equals(part.id)));}}
    @Test public void overlappingDormersAreRejected(){RoofPlan p=plan(1,false);RoofFeature a=feature(p,1),b=feature(p,2);b.id=2;p.features.add(a);p.features.add(b);RoofPlanner.solve(p);assertFalse(p.valid());assertTrue(p.error.contains("overlapping"));}
    @Test public void roofWindowsCannotStraddleAMansardBend(){RoofPlan p=plan(1,false);p.mansard=1;RoofFeature f=feature(p,0);f.u=2;p.features.add(f);RoofPlanner.solve(p);assertFalse(p.valid());assertTrue(p.error.contains("break"));}
    @Test public void everyDesignedVertexAndCollisionBoxStaysInItsCell(){RoofPlan p=plan(1,true);p.features.add(feature(p,1));RoofPlanner.solve(p);assertTrue(p.error,p.valid());for(RoofCell c:p.cells.values()){RoofMeshes.Mesh m=RoofMeshes.get(c,0);for(RoofMeshes.Face f:m.faces)for(double[] v:f.vertices)for(int i=0;i<3;i++)assertTrue("vertex "+v[i],v[i]>=-1e-8&&v[i]<=1+1e-8);for(AxisAlignedBB b:m.boxes)assertTrue(b.minX>=0&&b.minY>=0&&b.minZ>=0&&b.maxX<=1&&b.maxY<=1&&b.maxZ<=1);}}
    @Test public void everyRooflightFacingPitchAndPoseIsClippedAndTexturedInSashSpace(){for(int pitch:new int[]{16,32,64})for(net.minecraft.util.EnumFacing face:net.minecraft.util.EnumFacing.HORIZONTALS)for(boolean open:new boolean[]{false,true}){RoofWindow w=new RoofWindow("test",new BlockPos(15,80,15),0,0,0,8,pitch,0,0,face,false,false,open,false);int count=0;for(BlockPos at:RoofWindowGeometry.candidates(w)){RoofMeshes.Mesh m=RoofWindowGeometry.mesh(w.slice(at));for(RoofMeshes.Face f:m.faces){for(double[] v:f.vertices){for(int i=0;i<3;i++)assertTrue(v[i]>=-1e-8&&v[i]<=1+1e-8);assertEquals(5,v.length);}count++;}}assertTrue(count>0);}}
    @Test public void identicalRoofsShareTheirMeshesDespiteDifferentDrawingIds(){RoofPlan a=plan(1,false),b=plan(1,false);assertNotEquals(a.id,b.id);for(long k:a.cells.keySet())assertSame(RoofMeshes.get(a.cells.get(k),0),RoofMeshes.get(b.cells.get(k),0));}
    @Test public void dormerCheeksHaveIndependentClosedTopAndBottomPlanes(){RoofPlan p=plan(1,false);p.features.add(feature(p,2));RoofPlanner.solve(p);assertTrue(p.error,p.valid());int tapered=0;for(RoofCell c:p.cells.values())for(RoofPart part:c.parts)if(part.kind==RoofPart.WALL)for(int i=0;i<part.data.length;i+=8)if((part.data[i+7]&2)!=0){tapered++;assertTrue((short)part.data[i+6]<=0);assertTrue((short)(part.data[i+6]>>16)<=0);for(RoofMeshes.Face f:RoofMeshes.get(c,0).faces)for(double normal:f.normal)assertTrue(Double.isFinite(normal));}assertTrue(tapered>0);}
    @Test public void dormerWindowsCanBeReplacedWithoutLeavingOldWindowFragments(){RoofPlan p=plan(1,false);RoofFeature parent=feature(p,1);p.features.add(parent);RoofPlanner.solve(p);RoofWindow old=null;for(RoofCell c:p.cells.values())for(RoofWindow w:c.windows)old=w;assertNotNull(old);RoofFeature panel=new RoofFeature();panel.id=2;panel.type=RoofFeature.SOLID_PANEL;panel.parent=1;panel.u=old.owner.getX();panel.v=old.owner.getZ();panel.y=old.owner.getY();panel.width=1;panel.facing=old.facing.getHorizontalIndex();p.features.add(panel);RoofPlanner.solve(p);assertTrue(p.error,p.valid());for(RoofCell c:p.cells.values()){assertFalse(c.empty());for(RoofWindow w:c.windows)assertFalse(w.id.equals(old.id));}assertTrue(p.cells.get(old.owner.toLong()).parts.stream().anyMatch(a->a.kind==RoofPart.WALL));}
    @Test public void dormersMeetTheMainRoofWithClippedValleys(){RoofPlan p=plan(1,false);p.features.add(feature(p,1));RoofPlanner.solve(p);assertTrue(p.error,p.valid());int triangular=0;boolean restored=false;for(RoofCell c:p.cells.values())for(RoofPart part:c.parts){assertFalse(part.id.contains(":return:"));for(int i=0;i<part.data.length;i+=8)if((part.data[i+7]&4)!=0){triangular++;restored|=part.id.startsWith("main:");}}assertTrue(triangular>0);assertTrue("main covering continues behind the actual valley",restored);}
    @Test public void roofWindowRevealMatchesItsChosenCovering(){for(int cover=1;cover<=3;cover++){RoofPlan p=plan(1,false);RoofFeature f=feature(p,0);f.cover=cover;p.features.add(f);RoofPlanner.solve(p);assertTrue(p.error,p.valid());for(RoofCell c:p.cells.values())for(RoofWindow w:c.windows){assertEquals(cover==1?16:4,w.rise32);assertEquals(w,RoofWindow.read(w.write()));}}}
    @Test public void removedWindowOwnershipSurvivesReloadUntilExplicitReconstruction(){RoofData d=new RoofData();UUID id=UUID.randomUUID();d.removeWindow(id,"window:1");RoofData restored=new RoofData();restored.readFromNBT(d.writeToNBT(new NBTTagCompound()));assertTrue(restored.removed(id,"window:1"));restored.restoreWindow(id,"window:1");assertFalse(restored.removed(id,"window:1"));}
    @Test public void pendingFloorTrimsDoNotHideTheExistingRoofFromInteractions(){RoofData data=new RoofData();RoofPlan built=plan(1,false);data.savePlan(built);RoofPlan draft=built.settingsCopy();draft.minX=10;draft.maxX=13;draft.revision++;data.draft(draft);assertEquals(10,data.drawing(built.id).minX);assertEquals(0,data.interaction(built.id,new BlockPos(0,70,5)).minX);RoofData copy=new RoofData();copy.readFromNBT(data.writeToNBT(new NBTTagCompound()));assertEquals(0,copy.interaction(built.id,new BlockPos(0,70,5)).minX);}
    @Test public void partialConstructionCanUseTheDraftBeforeAnyCompletedRoofExists(){RoofData data=new RoofData();RoofPlan draft=plan(1,false);data.draft(draft);assertNotNull(data.interaction(draft.id,new BlockPos(3,70,5)));}
    @Test public void featureSettingsAndProfilesSurviveSaveReload(){RoofPlan p=plan(1,false);p.features.add(feature(p,2));RoofPlanner.solve(p);assertTrue(p.error,p.valid());RoofPlan q=RoofPlan.read(p.write(new NBTTagCompound()));assertEquals(p.cells,q.cells);assertEquals(1,q.features.size());assertEquals(p.cells,RoofPlanner.solve(q).cells);}
}
